import SwiftUI

/// Preview the saved generated bytes before the user explicitly starts printing.
struct InvoiceGeneratedDocumentView: View {
    @Environment(\.dismiss) private var dismiss
    let document: InvoiceDocument
    let isAuthorized: () -> Bool

    var body: some View {
        NavigationStack {
            Group {
                if isAuthorized() {
                    PDFPreview(document: document)
                } else {
                    ContentUnavailableView("auth.unavailable", systemImage: "lock")
                }
            }
            .navigationTitle("documents.title")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("documents.close") { dismiss() }
                }
                ToolbarItem(placement: .primaryAction) {
                    if isAuthorized() {
                        PrintDocumentButton(document: document, isAuthorized: isAuthorized)
                            .frame(minWidth: 100, minHeight: 44)
                    }
                }
            }
        }
        #if os(macOS)
        .frame(minWidth: 600, minHeight: 650)
        #endif
    }
}
